public void initValue()
{
    MarkupAutoTable markupAutoTable = this.cursor();

    next initValue();

    if (this.isGupCustMarkupAutoSetup())
    {
        markupAutoTable.PricingGroupCodeHeader = GUPGroupAll::All;
        markupAutoTable.PricingGroupCodeLine = GUPGroupAll::All;
        markupAutoTable.PriceComponentType = GUPPriceComponent::AutoCharges;
        markupAutoTable.AccountCode = TableGroupAll::All;
        markupAutoTable.ItemCode = TableGroupAll::All;
        markupAutoTable.IsGupMarkupAuto = NoYes::Yes;
    }
}

public void init()
{
    next init();

    QueryBuildDataSource qbds = this.queryBuildDataSource();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        qbds.addRange(fieldNum(MarkupAutoTable, IsGupMarkupAuto)).value(any2Str(NoYes::Yes));
    }
    else
    {
        qbds.addRange(fieldNum(MarkupAutoTable, IsGupMarkupAuto)).value(any2Str(NoYes::No));
    }
}

public int active()
{
    if (this.isGupCustMarkupAutoSetup())
    {
        MarkupAutoTable markupAutoTable = this.cursor();
        element.enablePriceAttributeGroupEdit(markupAutoTable.PriceComponentCodeName != '');
    }

    return next active();
}

public boolean validateWrite()
{
    boolean ret = next validateWrite();

    if (this.isGupCustMarkupAutoSetup())
    {
        MarkupAutoTable markupAutoTable, currentMarkupAutoTable = this.cursor();;

        select firstonly markupAutoTable
            where markupAutoTable.Description == currentMarkupAutoTable.Description 
               && markupAutoTable.RecId != currentMarkupAutoTable.RecId;

        if (markupAutoTable.RecId)
        {
            ret = ret && checkFailed("@GlobalUnifiedPricing:AutoChargeDescriptionDuplicationError");
        }
    }

    return ret;
}

private boolean isGupCustMarkupAutoSetup()
{
    return FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) 
        && this.formRun().args().parmEnum() == MarkupModuleType::Cust;
}
